import { useEffect, useState } from "react";
import api from "./api";

export default function CodeEditorPage() {
  const userId = localStorage.getItem("userId");

  const [language, setLanguage] = useState("python");
  const [code, setCode] = useState("");
  const [fontSize, setFontSize] = useState(16);

  const [levels, setLevels] = useState([]);
  const [currentLevel, setCurrentLevel] = useState(null);
  const [level, setLevel] = useState(null);

  const [userInput, setUserInput] = useState("");
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);

  /* ================= LOAD LEVEL LIST ================= */
  useEffect(() => {
    async function loadLevels() {
      const res = await api.get(`/levels/${userId}`);
      setLevels(res.data.levels);
      setCurrentLevel(res.data.currentLevel);
    }
    loadLevels();
  }, [userId]);

  /* ================= LOAD CURRENT LEVEL ================= */
  useEffect(() => {
    if (!currentLevel) return;

    async function loadCurrentLevel() {
      const res = await api.get(`/level/${userId}`);
      setLevel(res.data.level);
    }
    loadCurrentLevel();
  }, [currentLevel, userId]);

  /* ================= RUN CODE ================= */
  const handleRun = async () => {
    setLoading(true);
    setOutput("");

    try {
      const res = await api.post("/run", {
        code,
        language,
        userId,
        stdin: userInput   // ✅ IMPORTANT FIX
      });

      setOutput(res.data.userOutput || "");
    } catch (err) {
      setOutput(err.response?.data?.message || "Execution error");
    } finally {
      setLoading(false);
    }
  };

  /* ================= SUBMIT CODE ================= */
  const handleSubmit = async () => {
    setLoading(true);
    setOutput("");

    try {
      const res = await api.post("/run", {
        code,
        language,
        userId,
        stdin: userInput   // ✅ IMPORTANT FIX
      });

      setOutput(res.data.userOutput || "");

      if (res.data.success) {
        alert("✅ Correct! Level unlocked");
        window.location.reload();
      } else {
        alert("❌ Wrong answer");
      }
    } catch (err) {
      setOutput(err.response?.data?.message || "Execution error");
    } finally {
      setLoading(false);
    }
  };

  if (!level) return <h2 style={{ color: "white" }}>Loading...</h2>;

  return (
    <div style={{ background: "#0f172a", minHeight: "100vh", color: "white", padding: 20 }}>
      <h2>Level {level.level_no}: {level.title}</h2>
      <p>{level.description}</p>

      <textarea
        value={code}
        onChange={(e) => setCode(e.target.value)}
        placeholder={`Write ${language} code`}
        style={{ width: "100%", height: 300, fontSize }}
      />

      <br /><br />

      <button onClick={handleRun}>▶ Run</button>
      <button onClick={handleSubmit} style={{ marginLeft: 10 }}>✔ Submit</button>

      <h4>Sample Input</h4>
      <pre>{level.input_data || "N/A"}</pre>

      <h4>Your Input</h4>
      <textarea
        value={userInput}
        onChange={(e) => setUserInput(e.target.value)}
        style={{ width: "100%", height: 80 }}
      />

      <h4>Expected Output</h4>
      <pre>{level.expected_output}</pre>

      <h4>Your Output</h4>
      <pre>{loading ? "Running..." : output}</pre>
    </div>
  );
}

/* ================= INLINE STYLES ================= */
const styles = {
  app: {
    background: "#0f172a",
    color: "#f1f5f9",
    minHeight: "100vh",
    fontFamily: "Inter, sans-serif",
  },
  header: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    background: "#1e293b",
    padding: "10px 20px",
    boxShadow: "0 4px 10px rgba(0,0,0,0.4)",
  },
  logo: { fontSize: "1.5rem", fontWeight: "bold", color: "#38bdf8" },
  controls: { display: "flex", gap: "15px", alignItems: "center" },
  choice: { padding: "6px", borderRadius: "6px", border: "none" },
  fontBtn: {
    marginLeft: "5px",
    padding: "6px 10px",
    borderRadius: "6px",
    border: "none",
    background: "#334155",
    color: "#f1f5f9",
    cursor: "pointer",
  },
  body: { display: "flex", padding: 20, gap: 20 },
  sidebar: { width: 200 },
  levelBtn: {
    display: "block",
    width: "100%",
    marginBottom: 8,
    padding: 10,
    borderRadius: 6,
    border: "none",
    cursor: "pointer",
    fontWeight: "bold",
  },
  current: { background: "#4caf50", color: "white" },
  completed: { background: "#2196f3", color: "white" },
  locked: { background: "#475569", color: "#cbd5e1", cursor: "not-allowed" },
  main: { flex: 1, background: "#1e293b", padding: 20, borderRadius: 10 },
  levelTitle: { color: "#38bdf8" },
  description: { marginBottom: 15 },
  editorBox: { border: "1px solid #334155", borderRadius: 8, overflow: "hidden" },
  actions: { marginTop: 10 },
  runBtn: {
    padding: "8px 16px",
    borderRadius: 6,
    border: "none",
    cursor: "pointer",
    fontWeight: "bold",
    background: "#3b82f6",
    color: "white",
  },
  submitBtn: {
    padding: "8px 16px",
    borderRadius: 6,
    border: "none",
    cursor: "pointer",
    fontWeight: "bold",
    background: "#4caf50",
    color: "white",
    marginLeft: 10,
  },
  sampleInput: { marginTop: 15 },
  userInput: {
    width: "100%",
    height: 60,
    borderRadius: 6,
    padding: 8,
    background: "#0f172a",
    color: "#f1f5f9",
    border: "1px solid #334155",
  },
  outputs: { display: "flex", gap: 20, marginTop: 20 },
  expected: {
    flex: 1,
    background: "#334155",
    padding: 10,
    borderRadius: 6,
    color: "#f1f5f9",
  },
  actual: {
    flex: 1,
    background: "#334155",
    padding: 10,
    borderRadius: 6,
    color: "#f1f5f9",
  },
};
